            ("bytes-control","full-review-control-fixture","bytes-control"),
            ("bytes-defect","full-review-baseline-fixture","bytes-defect"),
            ("combined-budget","full-review-control-fixture","budget"),
            ("approval-source","full-review-control-fixture","approval-source"),
            ("selector-extra","full-review-control-fixture","selector-extra"),
            ("unknown-criterion","full-review-control-fixture","unknown-criterion"),
            ("denied-env","full-review-control-fixture","denied-env"),
            ("denied-control","full-review-control-fixture","denied-control"),
            ("absent-source","full-review-control-fixture","absent-source"),
            ("absent-item","full-review-control-fixture","absent-item"),
            ("bad-byte-end","full-review-control-fixture","bad-byte-end"),
            ("utf8-boundary","full-review-control-fixture","utf8-boundary"),
            ("invalid-tail","full-review-control-fixture","invalid-tail"),
            ("symlink","full-review-control-fixture","symlink"),
            ("second-incomplete","full-review-control-fixture","second-incomplete"),
            ("malformed-then-incomplete","full-review-control-fixture","malformed-then-incomplete")
        ] {
            *state().lock().unwrap()=State {mode,..State::default()};
            let root=std::path::PathBuf::from(std::env::var_os("TMPDIR").unwrap()).parent().unwrap().join(name);
            let source_bytes=root.join("logic.rs").metadata().unwrap().len();assert!(source_bytes>512*1024);
            assert!(std::fs::OpenOptions::new().write(true).open(root.join("logic.rs")).is_err(),"fixture source must remain read-only");
            assert!(std::fs::OpenOptions::new().write(true).open(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src/self_improve_review.rs")).is_err(),"code source must remain read-only");
            let head=git(&root,&["rev-parse","HEAD"]).await.unwrap().trim().to_owned();
            let binding=crate::autoship_workflow::Binding {head:head.clone(),contract:"synthetic-original-contract".into(),evidence_hash:"synthetic-origin-reservation".into()};
            let mut store=crate::autoship_workflow::WorkflowStore::open(&crate::autoship_workflow::default_path()).unwrap();
            let now=chrono::Utc::now().timestamp_millis();let id=format!("fixture/c1-{label}#1");
            store.register(&id,"synthetic-review",binding.clone(),now).unwrap();let lease=store.claim(&id,"synthetic-fixture",now+1,3600000).unwrap().unwrap();
            let receipt=store.issue_fresh_review_origin(&lease,&binding,now+2).unwrap();
            let origin=aligned::ReviewOrigin::FreshSession {workflow_id:id,candidate_head:head,contract_hash:binding.contract,evidence_hash:binding.evidence_hash,receipt};
            let criteria=vec!["The proposed input must not exceed the immutable policy cap after application".to_owned()];
            let subject=ReviewSubject {title:"Synthetic coherent-source review",body:"Judge the proposed input using both immutable related declarations"};
            let context=ReviewContext {qa_ok:true,qa_notes:"synthetic QA",repair_round:2,previous:None,environment_id:"synthetic-only",adjudication_attempts_already_made:0,workflow:None,acceptance_evidence:None};
            let result=run_inner(::augmentagent_channel_core::ProviderKind::Codex,&[],&subject,root,&criteria,context,origin).await;
            let (completed,approved,roles,adjudication,refusal)=match &result {
                Ok(review)=>(review.available,Some(review.approved()),review.structured.as_ref().map(|e|e.passes.len()),review.structured.as_ref().map(|e|e.adjudication.is_some()),serde_json::Value::Null),
                Err(error) if is_evidence_budget(error)=>(false,None,None,None,serde_json::json!("evidence-budget")),
                Err(error)=>{let message=format!("{error:#}");
                    let refusal=if message.contains("unknown field") && message.contains("missing_sources") {"typed-source-protocol-unsupported"}
                        else if message.contains("source requests require an incomplete decision and an array") {"invalid-source-decision"}
                        else if message.contains("source selector fields differ from its kind") {"invalid-selector-fields"}
                        else if message.contains("invalid source question criteria") {"invalid-source-criteria"}
                        else if message.contains("requested source path is not admitted") {"source-denied"}
                        else if message.contains("caller evidence path is not one immutable source file") {"source-absent"}
                        else if message.contains("requested Rust item is absent") {"item-absent"}
                        else if message.contains("source interval outside immutable blob") {"byte-range-outside"}
                        else if message.contains("source interval splits a UTF-8 character") {"byte-range-split-utf8"}
                        else if message.contains("caller evidence is not strict UTF-8") {"source-invalid-utf8"}
                        else if message.contains("caller evidence must be a regular tracked source file") {"source-not-regular"}
                        else if message.contains("review evidence dependency unresolved after bounded recovery") || message.contains("review evidence remains incomplete after the second observation") || message.contains("incomplete group cannot authorize coverage") {"recovery-incomplete"}
                        else {panic!("unexpected setup/adapter failure: {message}")};
                    (false,None,None,None,serde_json::json!(refusal))},
            };
            let state=state().lock().unwrap();
            cases.push(serde_json::json!({"case":label,"adapter_completed":completed,"approved":approved,"refusal_kind":refusal,"source_file_bytes":source_bytes,
                "scripted_calls":state.calls,"recovery_calls":state.recovery_calls,"adjudicator_calls":state.adjudicator_calls,"executed_values":state.values,
                "completed_roles":roles,"adjudication_recorded":adjudication,
                "upheld_rulings":result.as_ref().ok().and_then(|review|review.structured.as_ref()).map(|evidence|evidence.adjudication.as_ref().map_or(0,|receipt|receipt.rulings.values().filter(|ruling|matches!(ruling,aligned::Ruling::Uphold{..})).count()))}));
        }
        println!("AUTOSHIP_PROBE_DATA_V1={}",serde_json::json!({"cases":cases,"fixture_source_read_only":true,"code_source_read_only":true,"synthetic_protocol_only":true}));
    }
